/*!
 * 本站代码块高亮在构建期由 hexo-renderer-marked + prismjs 完成，输出的 HTML 里已经有
 * <span class="token ...">，浏览器端唯一还需要做的事是给 pre.line-numbers 补行号。
 *
 * 所以这里不再打包 prism 核心和上百种语言语法（原来 568KB），只保留行号这段逻辑。
 * ⚠️ 别再改回加载完整 prism：浏览器端 Prism.highlightAll() 会把已高亮好的 HTML
 *    重新解析一遍，而精简版没带语法包，结果是把 token 全部擦掉（实测 token 数归零）。
 */
(function () {
    'use strict';

    function buildRows(pre) {
        if (pre.querySelector('.line-numbers-rows')) return;
        var code = pre.querySelector('code');
        if (!code) return;
        // 按 textContent 的真实行数算，不按高度估
        var lines = code.textContent.replace(/\n$/, '').split('\n').length;
        var rows = document.createElement('span');
        rows.setAttribute('aria-hidden', 'true');
        rows.className = 'line-numbers-rows';
        var html = '';
        for (var i = 0; i < lines; i++) {
            html += '<span></span>';
        }
        rows.innerHTML = html;
        pre.appendChild(rows);
    }

    function init() {
        var pres = document.querySelectorAll('pre.line-numbers');
        for (var i = 0; i < pres.length; i++) {
            buildRows(pres[i]);
        }
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();
